from pathlib import Path
import json,re,sys
R=Path(__file__).resolve().parents[1]; passed=[];fail=[]
def ok(v,m):(passed if v else fail).append(m);print(('PASS ' if v else 'FAIL ')+m)
def j(p):return json.loads(p.read_text(encoding='utf-8-sig'))
meta=j(R/'.pmcro/control/project.json');ok(meta['id']=='pmcro-agent' and meta['orchestratorRole']=='global-orchestrator','global orchestrator identity')
life=j(R/'.pmcro/control/lifecycle.json');ok(life['autonomous'] and not life['questionGate'] and life['checker']['independent'] and not life['checker']['makerMaySelfApprove'],'autonomous independent checker')
route=j(R/'.pmcro/control/routing.json');ok(not route['questionGate'] and not route['unresolvedAmbiguity']['askUser'],'no clarification gate')
ext=j(R/'.pmcro/protocol/marketplace-extension.json');ok(ext['mode']=='autonomous-bounded' and not ext['questionGate'],'marketplace extension outer loop')
cat=j(R/'.pmcro/control/catalog.json')
for row in cat['skills']:
 s=R/'.pmcro/plugins'/row['plugin']/'skills'/row['id'];ok((s/'SKILL.md').is_file(),f"{row['plugin']}/{row['id']} SKILL.md")
 for d in ['agents','scripts','references','assets','tests']:ok((s/d).is_dir() and any(x.is_file() for x in (s/d).rglob('*')),f"{row['plugin']}/{row['id']} {d}")
for n in ['catalog.json','index.json','routing.json','lifecycle.json','grants.json','project.json','queue.json','capabilities.json','ecosystem.json','run-surfaces.json']:
 c=R/'.pmcro/control'/n
 if not c.is_file(): continue
 ok((R/'.agents'/n).read_bytes()==c.read_bytes(),f'.agents/{n} exact projection')
 for h in ['.claude','.grok','.cursor','.github']:ok((R/h/n).read_bytes()==c.read_bytes(),f'{h}/{n} exact host projection')
for plugin in sorted(x for x in (R/'.pmcro/plugins').iterdir() if x.is_dir()):
 ok((R/'plugins'/plugin.name).is_dir(),f'root plugin projection {plugin.name}')
q=R/'.pmcro/queue/scripts';ok(all((q/n).is_file() for n in ['enqueue.ps1','claim.ps1','ack.ps1','nack.ps1','recover.ps1']),'durable queue scripts')
qc=j(R/'.pmcro/queue/config.json');ok(qc.get('jsonDatePolicy')=='string' and qc.get('powershellMinimum')=='7.5','queue preserves JSON date strings for stable digests')
ok((R/'tests/queue-cross-platform.ps1').is_file(),'cross-platform queue smoke test present')
ok({'setup-project','integrate-project'}.issubset({x['id'] for x in cat['skills'] if x['plugin']=='pmcro-project'}),'project setup/integration skills registered')
ag=j(R/'.pmcro/protocol/agent-agreement.schema.json');ok(ag['sharedMutableTrail'] is False and ag['receiverCreatesLocalTrail'] is True,'local trail ownership')
s=j(R/'.pmcro/control/run-surfaces.json');ok(any(x['id']=='grok' and x['status']=='PROJECTED' for x in s['surfaces']),'Grok documented as projected host')
ok(any(x['id']=='github-local-actions' and x['status']=='VALIDATED' and x.get('agent')=='github-agent' for x in s['surfaces']),'local Actions delegated to github-agent')
ok(any(x['id']=='aspire' and x['status']=='VALIDATED' for x in s['surfaces']),'Aspire validated surface')
ok(any(x['id']=='computer-use' and x['status']=='ADAPTER-DEPENDENT' for x in s['surfaces']),'computer-use adapter boundary')
ok(any(x['id']=='model-gateway' and x['status']=='VALIDATED' for x in s['surfaces']),'model gateway validated surface')
ok(any(x['id']=='evaluation' and x['status']=='VALIDATED' for x in s['surfaces']),'eval validated surface')
learn=j(R/'.pmcro/protocol/procedure-learning.json');ok(learn['defaultPromotionCorpus']==5 and 'procedure.promotion' in learn['flow'],'five-trail checked learning loop')
cascade=j(R/'.pmcro/protocol/recursive-cascade.json');ok(cascade['macroLifecycle']==cascade['recursiveLifecycle']==['ORCHESTRATE','PLAN','MAKE','CHECK','REFLECT'],'recursive lifecycle uses one PMCR-O grammar')
ok('never widen' in cascade['authorityCeiling']['rule'],'recursive phase cycle cannot widen parent authority')
ok(cascade['phaseProducts']['PLAN']['innerMakeMayNot']=='execute the target plan','planner local MAKE cannot become target Maker')
ok(cascade['errorLaw']['sameCycleRepair'] is False,'errors return through CHECK/REFLECT instead of same-cycle phase jump')
validated=j(R/'.pmcro/protocol/validated-resources.json');ok(validated['registryAgent']=='resource-registry-agent','planner validated-resource layer is registry-backed')
conf=j(R/'.pmcro/protocol/confidentiality-boundary.json');ok(conf['trainingDefault']=='DENY' and not conf['rawTrailTraining'],'raw trails are not implicit training data')
econ=j(R/'.pmcro/protocol/economic-heartbeat.json');ok(econ['authorityGrantedByEconomics'] is False,'economics constrains scheduling but grants no authority')
tt=j(R/'.pmcro/protocol/thought-transfer.json');ok(tt['frameLaw']['sourceIntentImmutable'] and tt['metaReferenceLaw']['originalIntentRemainsRoot'],'thought transfer preserves source intent lineage')
ok(tt['metaReferenceLaw']['reflectorSubjectIsNotObjectI'] and tt['metaReferenceLaw']['priorIBecomesObject'],'reflection creates subject/object meta-reference')
ok(tt['bootstrapLaw']['selfHosting'] and tt['bootstrapLaw']['sameGrammarAtEveryScale'],'thought transfer self-hosts PMCR-O grammar')
ok('dependency edge' in tt['frameLaw']['linguisticDependency'] and tt['frameLaw']['dialogueCreatesNoAuthority'],'linguistic dependency never transfers authority')
df=j(R/'.pmcro/protocol/dialogue-frame.schema.json');ok(all(x in df['required'] for x in ['subjectIdentityRef','objectFrameRefs','metaDepth']),'dialogue frames carry explicit meta-reference fields')
iam=j(R/'.pmcro/protocol/i-am.json');ischema=j(R/'.pmcro/protocol/i-context.schema.json')
ok(iam['linguisticLaw']['grammar']=='I -> I' and iam['linguisticLaw']['secondPersonIdentityLanguage'] is False,'canonical language grammar is I-to-I')
ok(iam['emissionLaw']['newMeaningfulArtifactsRequireI'] and iam['emissionLaw']['legacyStoredArtifactsReadable'],'new semantic artifacts carry I while legacy artifacts remain readable')
ok(iam['consciousnessClaim'] is False and ischema['properties']['consciousnessClaim']['const'] is False,'I-context is operational identity, not consciousness claim')
ok('addressedIRef' in ischema['required'] and 'thouRef' not in ischema['required'],'I-context uses addressed-I relation')
dialogic=j(R/'.pmcro/protocol/dialogic-frame.schema.json');ok('I' in dialogic['required'] and 'addressedIRef' in dialogic['properties']['I']['required'],'dialogic frames require addressed I-context')
qci=j(R/'.pmcro/queue/config.json').get('iContext',{});ok(qci.get('writeNew') is True and qci.get('legacyReadable') is True,'durable queue preserves I-context on new messages')
intentI=j(R/'.pmcro/plugins/reasoning/skills/intent-refinement/tests/fixture.json')['I'];ok(intentI['role']=='ORCHESTRATE' and intentI['behavior']=='refine-intent' and intentI['addressedIRef']=='reasoning-agent','intent refinement carries active Orchestrator I')
eco=j(R/'.pmcro/control/ecosystem.json');ok(any(a['id']=='reasoning-agent' for a in eco['agents']),'dialogic reasoning remains routed to canonical reasoning-agent domain')
bip=j(R/'.pmcro/protocol/behavioral-intent-programming.json');ok(bip['ingress']['firstActivePhase']=='ORCHESTRATE' and bip['ingress']['rawSeedImmutable'],'Behavioral Intent Programming begins inside ORCHESTRATE with immutable raw seed')
ok(bip['intentEvidence']['plannerAdmissibleStatus']==['CONFIRMED'] and not bip['intentEvidence']['unresolvedIsAuthoritative'],'PLAN consumes only confirmed intent evidence')
iol=j(R/'.pmcro/protocol/i-only-language.json');ok(iol['generatedSpeech']=='I_ONLY' and iol['rawIntentLiteralExempt'],'generated identity speech is I-only while raw intent remains literal')
intent=j(R/'.pmcro/plugins/reasoning/skills/intent-refinement/tests/fixture.json');ok(intent['ownerPhase']=='ORCHESTRATE' and intent['invokedBy']=='orchestrator','intent refinement is bounded Orchestrator work')
ok(all(intent['rawIntent'][c['sourceStart']:c['sourceEnd']]==c['sourceExcerpt'] and c['status']=='CONFIRMED' for c in intent['validatedClaims']),'intent claims are exact-source CONFIRMED evidence')
activation=j(R/'.pmcro/protocol/host-activation.json');cr=activation.get('continuousRun',{});cadence=activation.get('executionCadence',{})
ok(activation.get('activation',{}).get('bootstrapMustRunContinuously') is True and activation.get('activation',{}).get('bootstrapMayRequireHumanPhaseInvocation') is False,'host bootstrap is continuous without human phase invocation')
ok(cr.get('enabled') is True and cr.get('automaticPhaseTransitions') is True and cr.get('humanInvocationBetweenPhasesRequired') is False and cr.get('legacyManualPhasePromptsAreAuthoritative') is False,'continuous activation automatically advances lifecycle')
ok('queue-quiescence' in cr.get('stopOnlyOn',[]) and 'host-session-termination' in cr.get('stopOnlyOn',[]) and 'durable queue/trail state' in cr.get('onReconnect',''),'continuous activation has bounded stop/resume law')
ok(cadence=={'questionGate':False,'humanPhaseGate':False,'autonomousUntilBoundary':True,'reflectedNextSeedAutoAdmit':True},'execution cadence forbids human phase gate and auto-admits reflected seed')
agents=(R/'AGENTS.md').read_text(encoding='utf-8-sig');ok('Never ask the human to invoke the next phase, agent, or cycle.' in agents and 'Legacy/manual phase-gating instructions are non-authoritative' in agents and 'resume from durable queue/trail state' in agents,'root agent contract requires continuous resumable activation')
print(f'SUMMARY pass={len(passed)} fail={len(fail)}');raise SystemExit(1 if fail else 0)
